const QUESTIONS=[
  {id:'immediate_intent',eyebrow:'A useful starting point',title:'What would you like FinTutor to help you do first?',helper:'This only shapes where we begin. It is not a recommendation.',options:[['Understand the basics','learn_basics'],['See how my financial picture fits together','connect_picture'],['Understand something I already have','understand_existing'],['Explore a goal or scenario','model_future'],['Build a learning routine','build_routine'],['Ask Arya a question','ask_arya'],['Just look around','explore'],['Prefer not to choose','undisclosed']]},
  {id:'earning_context',eyebrow:'Your current context',title:'Which description is closest to where you are today?',helper:'No income amount is needed.',options:[['Studying','student'],['Preparing to start earning','pre_earning'],['Started earning recently','early_earner'],['Working for a few years','established_earner'],['My situation or income varies','variable_or_transitioning'],['Prefer not to say','undisclosed']]},
  {id:'responsibility_context',eyebrow:'The people money supports',title:'How are day-to-day financial responsibilities arranged?',helper:'Choose the closest fit. You can change this later.',options:[['Mostly just me','self'],['Shared or family expenses','shared'],['Others depend on me','dependents'],['It changes month to month','variable'],['Prefer not to say','undisclosed']]},
  {id:'exposure_flags',eyebrow:'What you have encountered',title:'Which money topics are already part of your life?',helper:'Choose any that fit. We still do not need amounts or account details.',multi:true,options:[['Spending','spending'],['Saving','saving'],['Investing','investing'],['Borrowing or EMIs','borrowing'],['Insurance','insurance'],['Financial goals','goals'],['Workplace benefits or tax','workplace_and_tax'],['None of these yet','none'],['Not sure','unsure'],['Prefer not to say','undisclosed']]},
  {id:'familiarity',eyebrow:'How explanations should begin',title:'How familiar do these topics generally feel?',helper:'This changes explanation depth, not what you are allowed to explore.',options:[['Start from the foundations','foundations'],['I know the working basics','working_basics'],['I am connecting the pieces','connecting'],['I want deeper context','deeper_context'],['It varies by topic','variable'],['Prefer not to say','undisclosed']]}
];
const LABELS=Object.fromEntries(QUESTIONS.map(q=>[q.id,Object.fromEntries(q.options.map(([label,value])=>[value,label]))]));
const SENTINELS=new Set(['none','unsure','undisclosed']);
const scenarios={
  complete:{title:'New user completes all questions',prompt:'Confirm eligibility, answer all five questions, verify exposure exclusivity, understand Discovering and open every first-action destination.',fixture:'Aarav has no v2 or legacy state. Immediate intent can create one attributed suggestion.'},
  'skip-exit':{title:'Skip and continue to app',prompt:'Skip one question, then leave the remaining questions. Confirm the same access and single progression milestone as completing all five.',fixture:'No answer value appears in the event ledger.'},
  resume:{title:'Interrupted and resumed',prompt:'Relaunch the app and verify the exact current question returns with earlier saved answers intact.',fixture:'Aarav previously handled immediate intent and earning context.'},
  failure:{title:'Save failure and retry',prompt:'Fail the next save. Confirm the question does not advance, the choice is retained and explicit retry succeeds once.',fixture:'The first attempted responsibility answer returns a transport failure.'},
  lost:{title:'Lost response and stale conflict',prompt:'Commit an answer but lose its response, retry it, then send a different stale write. Verify reconciliation and no double advance.',fixture:'Fixture controls expose both failure shapes.'},
  legacy:{title:'Legacy invitation and voluntary start',prompt:'Confirm grandfathered access, dismiss the optional invitation, reset, start voluntarily, then use Not now before acknowledgement.',fixture:'No legacy track is displayed or translated into v2 answers.'},
  manage:{title:'View, change and clear context',prompt:'Change one answer, cancel another edit, fail and retry a save, then cancel and confirm clear. Verify progress remains.',fixture:'A handled record contains five normalized values.'},
  'auth-switch':{title:'Permission loss and account switch',prompt:'Deny a protected request, confirm context clears, then switch accounts during an in-flight response and inspect the discarded result.',fixture:'Aarav and Meera have isolated subject state.'},
  'offline-new':{title:'New user offline acknowledgement',prompt:'Go offline, acknowledge 18+, inspect the limited Home, try locked actions, restore connection and sync into question one.',fixture:'D-159 pending acknowledgement is local to Aarav and grants no ordinary data, Arya, calculation or progress.'}
};
const $=id=>document.getElementById(id);
let state={};
function blankAnswers(){return Object.fromEntries(QUESTIONS.map(q=>[q.id,null]));}
function freshState(){return {scenario:'complete',account:'Aarav',screen:'intro',question:0,answers:blankAnswers(),selection:[],handled:false,handledVia:null,events:[],online:true,pendingEligibility:false,failNext:false,lostCommitted:null,error:null,editing:null,confirmClear:false,cleared:false,requestGeneration:0};}
function announce(message){$('announcement').textContent='';requestAnimationFrame(()=>$('announcement').textContent=message)}
function log(message){$('fixture-log').textContent=message;announce(message)}
function updateLedger(){$('event-log').textContent=state.events.length?state.events.join(' | '):'No events.'}
function emitHandled(){if(!state.events.includes('onboarding_handled:v2'))state.events.push('onboarding_handled:v2');updateLedger()}
function btn(label,id,kind=''){return `<button${id?` id="${id}"`:''} class="${kind}">${label}</button>`}
function screen(content,classes=''){return `<section class="screen ${classes}">${content}</section>`}
function render(){
  $('account-label').textContent=`${state.account}'s account`;
  if(state.screen==='loading'){renderLoading();return}
  if(state.screen==='intro'){renderIntro();return}
  if(state.screen==='question'){renderQuestion();return}
  if(state.screen==='closing'){renderClosing();return}
  if(state.screen==='home'){renderHome(false);return}
  if(state.screen==='limited'){renderHome(true);return}
  if(state.screen==='manage'){renderManage();return}
  if(state.screen==='permission'){renderPermission();return}
}
function renderLoading(){$('app').innerHTML=screen(`<p class="brand-kicker">Preparing your starting point</p><h1>Checking your saved setup</h1><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div>`,'centered')}
function renderIntro(){
  $('app').innerHTML=screen(`<p class="brand-kicker">A quick start</p><h1>Make FinTutor useful for where you are today.</h1><p class="body">Five optional questions. No amounts or account details, and you can skip anything.</p><div class="age-card"><strong>FinTutor is currently for adults 18 and older.</strong><span>Continue to confirm that you are 18 or older.</span></div>${state.error?`<div class="error" role="alert">${state.error}</div>`:''}<div class="actions">${btn("I'm 18 or older. Begin",'start','primary')}${state.scenario==='legacy'?btn('Not now','not-now','text-button'):''}</div>`,'centered');
}
function renderQuestion(){
  const q=QUESTIONS[state.question];const selected=state.selection;const width=((state.question+1)/QUESTIONS.length)*100;
  const options=q.options.map(([label,value])=>`<button class="option" data-option="${value}" role="${q.multi?'checkbox':'radio'}" aria-checked="${selected.includes(value)}"><span>${label}</span>${selected.includes(value)?'<span class="check" aria-hidden="true">Selected</span>':''}</button>`).join('');
  $('app').innerHTML=screen(`<div class="question-header"><span class="progress-label">Question ${state.question+1} of 5</span><button id="global-exit" class="text-button">Continue to app</button></div><div class="progress" role="progressbar" aria-label="Question ${state.question+1} of 5" aria-valuemin="1" aria-valuemax="5" aria-valuenow="${state.question+1}"><span style="width:${width}%"></span></div><p class="brand-kicker">${q.eyebrow}</p><h1 class="question-title" tabindex="-1" id="question-title">${q.title}</h1><p class="helper">${q.helper}</p><div class="options" ${q.multi?'':'role="radiogroup"'}>${options}</div>${state.error?`<div class="error" role="alert">${state.error}</div>`:''}${q.multi?btn('Continue','continue-multi',selected.length?'primary':'primary',selected.length===0):''}<button id="skip" class="text-button">Skip this question</button>`);
  const multi=$('continue-multi');if(multi&&selected.length===0)multi.disabled=true;
}
function suggestion(){const v=state.answers.immediate_intent;if(['ask_arya','learn_basics'].includes(v))return'Ask Arya';if(['connect_picture','understand_existing'].includes(v))return'Something I manage';if(v==='model_future')return'Calculators and scenarios';if(v==='build_routine')return'Home';return null}
const handoffs=[['Ask Arya','Start with a question or teaching moment.'],['Something I manage','Add or understand a holding you already manage.'],['A goal','Create a goal or explore how planning works.'],['Calculators and scenarios','Try a calculator or model a what-if scenario.'],['Home','Look around without adding financial details.']];
function renderClosing(){const s=suggestion();$('app').innerHTML=screen(`<p class="brand-kicker">Your FinTutor journey</p><h1 tabindex="-1" id="closing-title">You are starting at Discovering.</h1><p class="body">That only means your FinTutor journey is beginning. It does not judge how much you know about money.</p><div class="notice">Pick any starting point. Every part of FinTutor stays available, and Home requires no financial details.</div><div class="handoff">${handoffs.map(([name,desc])=>`<button data-route="${name}" aria-label="${name}. ${desc}${s===name?' Suggested from what you chose.':''}"><span><strong>${name}</strong><span>${desc}</span>${s===name?'<span class="suggested">Suggested from what you chose</span>':''}</span><span class="chevron" aria-hidden="true">›</span></button>`).join('')}</div>`)}
function renderHome(limited){
  const limitedCopy=limited?`<div class="limited-banner" role="status"><strong>Setup is waiting to sync.</strong><br>You can look around this offline introduction. Connect before Arya, financial data, tools or progress become available.</div>`:'';
  const content=limited?`<div class="home-section"><h2>What FinTutor can help you understand</h2><p>Learn how personal-finance mechanisms connect. No financial data is available in this offline view.</p></div><div class="locked-list">${['Ask Arya','Portfolio','Goals','Calculators and scenarios','Learning progress'].map(x=>`<button data-locked="${x}">${x}<br><span class="small">Connect to continue</span></button>`).join('')}</div><div class="actions" style="margin-top:14px">${btn('Try syncing setup','sync','primary')}${btn('Sign out','sign-out','secondary')}</div>`:`<div class="home-section"><h2>Home is ready</h2><p>You can look around without adding financial details. Every destination remains available.</p><div class="actions">${btn('Personalization','open-manage')}${btn('Ask Arya','home-arya')}${btn('Portfolio','home-portfolio')}${btn('Goals','home-goals')}${btn('Tools','home-tools')}</div></div>${state.scenario==='legacy'?`<div class="notice"><strong>Personalize how Arya explains things</strong><p class="small">Five optional questions. No amounts or account details.</p><div class="actions inline">${btn('Personalize','voluntary-start','primary')}${btn('Not now','dismiss-invite','secondary')}</div></div>`:''}`;
  $('app').innerHTML=screen(`${limitedCopy}<div class="home-header"><p class="brand-kicker">Home</p><h1>${limited?'Limited offline view':`Welcome, ${state.account}`}</h1></div>${content}`);
}
function valueLabel(id,value){if(value===null)return'Not provided';const vals=Array.isArray(value)?value:[value];return vals.map(v=>LABELS[id][v]||'Not provided').join(', ')}
function renderManage(){
  const cards=QUESTIONS.map((q,i)=>{const edit=state.editing===q.id;return `<article class="context-card"><h2>${q.eyebrow}</h2><p class="value">${valueLabel(q.id,state.answers[q.id])}</p>${edit?editor(q):`<button data-edit="${q.id}">Change</button>`}</article>`}).join('');
  $('app').innerHTML=screen(`<p class="brand-kicker">Your context</p><h1>How FinTutor begins explanations</h1><p class="body">These optional categories do not limit what you can explore and contain no amounts or account details.</p>${state.cleared?'<div class="notice" role="status"><strong>Personalization context cleared</strong><br><span class="small">Arya will use a neutral starting point. Your progress remains.</span></div>':''}${state.error?`<div class="error" role="alert">${state.error}</div>`:''}<div class="context-list">${cards}</div><div class="clear-area"><h2>Clear personalization context</h2><p class="small">This replaces all five answers with Prefer not to say. Your learning progress is not removed.</p>${state.confirmClear?`<div class="actions inline">${btn('Yes, clear','confirm-clear','danger')}${btn('Keep answers','keep-answers')}</div>`:btn('Clear my context','clear','danger')}</div><button id="back-home" class="text-button">Back to Home</button>`);
}
function editor(q){const values=Array.isArray(state.answers[q.id])?state.answers[q.id]:state.answers[q.id]?[state.answers[q.id]]:[];return `<div class="editor"><div class="options">${q.options.map(([label,value])=>`<button class="option" data-manage-option="${value}" data-question="${q.id}" role="${q.multi?'checkbox':'radio'}" aria-checked="${values.includes(value)}"><span>${label}</span>${values.includes(value)?'<span class="check" aria-hidden="true">Selected</span>':''}</button>`).join('')}</div>${q.multi?btn('Save change','save-manage','primary'):''}<button id="cancel-edit" class="text-button">Cancel</button></div>`}
function renderPermission(){$('app').innerHTML=screen(`<div class="error" role="alert">Your session no longer has access. Personalization context has been cleared from this view.</div><h1>Sign in to continue</h1><p class="body">No prior account information remains on screen.</p>${btn('Sign in again','sign-in','primary')}`,'centered')}
function handleStart(){if(!state.online){state.pendingEligibility=true;state.screen='limited';state.error=null;render();log('Stored a subject-scoped pending acknowledgement. Opened limited offline Home. No progression event.');return}state.screen='question';state.question=0;state.error=null;render();focusHeading();log('Eligibility saved. Started question one.')}
function focusHeading(){setTimeout(()=>$('question-title, #closing-title')?.focus(),0)}
function applyAnswer(value){const q=QUESTIONS[state.question];const submitted=q.multi?[...state.selection]:value;if(state.failNext){state.failNext=false;state.error='We could not save that just now. Your choice is still here. Try again.';render();log('Save failed. Question and unsaved choice were retained.');return}
  if(state.lostCommitted){const lost=state.lostCommitted;if(lost.question===q.id&&JSON.stringify(lost.value)===JSON.stringify(submitted)){state.lostCommitted=null;advance(submitted,true);log('Retry matched the committed answer. Reconciled without a second advance.');return}}
  advance(submitted,false)
}
function advance(value,reconciled){const q=QUESTIONS[state.question];state.answers[q.id]=value;state.selection=[];state.error=null;if(state.question===QUESTIONS.length-1){state.handled=true;state.handledVia='completed';emitHandled();state.screen='closing';render();focusHeading();log(reconciled?'Reconciled handled state.':'All five prompts handled. One onboarding milestone emitted.')}else{state.question+=1;state.screen='question';render();focusHeading();if(!reconciled)log(`Saved ${q.eyebrow}. Advanced once.`)}}
function skip(){const q=QUESTIONS[state.question];state.selection=q.multi?['undisclosed']:['undisclosed'];applyAnswer(q.multi?undefined:'undisclosed')}
function globalExit(){QUESTIONS.forEach(q=>{if(state.answers[q.id]===null)state.answers[q.id]=q.multi?['undisclosed']:'undisclosed'});state.handled=true;state.handledVia='global_exit';state.selection=[];emitHandled();state.screen='closing';render();focusHeading();log('Global exit handled all remaining prompts. One onboarding milestone emitted. No question events.')}
function toggleExposure(value,manage=false){const list=manage?(Array.isArray(state.answers.exposure_flags)?[...state.answers.exposure_flags]:[]):[...state.selection];let next;if(list.includes(value))next=list.filter(x=>x!==value);else if(SENTINELS.has(value))next=[value];else next=[...list.filter(x=>!SENTINELS.has(x)),value];if(manage){state.answers.exposure_flags=next;state.cleared=false}else state.selection=next;render()}
function route(name){$('route-title').textContent=name;$('route-body').textContent='This controlled destination confirms navigation only. It receives no hidden recommendation or financial data from Onboarding.';$('route-dialog').showModal();log(`Opened ${name}.`)}
function scenarioState(name){const s=freshState();s.scenario=name;if(name==='skip-exit'){s.screen='question';s.question=1;s.answers.immediate_intent='explore'}if(name==='resume'){s.screen='question';s.question=2;s.answers.immediate_intent='ask_arya';s.answers.earning_context='student'}if(name==='failure'){s.screen='question';s.question=2;s.answers.immediate_intent='learn_basics';s.answers.earning_context='early_earner';s.failNext=true}if(name==='lost'){s.screen='question';s.question=1;s.answers.immediate_intent='connect_picture'}if(name==='legacy'){s.screen='home'}if(name==='manage'){s.screen='manage';s.handled=true;s.answers={immediate_intent:'learn_basics',earning_context:'early_earner',responsibility_context:'shared',exposure_flags:['saving','goals'],familiarity:'working_basics'};s.events=['onboarding_handled:v2']}if(name==='auth-switch'){s.screen='question';s.question=3;s.answers={immediate_intent:'understand_existing',earning_context:'established_earner',responsibility_context:'shared',exposure_flags:null,familiarity:null}}if(name==='offline-new'){s.online=false}s.events=name==='manage'?['onboarding_handled:v2']:[];return s}
function applyScenario(name){state=scenarioState(name);const s=scenarios[name];$('scenario-title').textContent=s.title;$('scenario-prompt').textContent=s.prompt;$('scenario-fixture').textContent=`Fixture: ${s.fixture}`;$('toggle-connection').textContent=state.online?'Go offline':'Restore connection';render();updateLedger();log(`Loaded scenario: ${s.title}.`)}
document.addEventListener('click',e=>{
  const t=e.target.closest('button');if(!t)return;
  if(t.id==='start'){handleStart();return}if(t.id==='not-now'){state.screen='home';render();log('Voluntary setup cancelled before acknowledgement. No write.');return}
  if(t.dataset.option){const q=QUESTIONS[state.question];if(q.multi){toggleExposure(t.dataset.option);return}state.selection=[t.dataset.option];render();applyAnswer(t.dataset.option);return}
  if(t.id==='continue-multi'){applyAnswer();return}if(t.id==='skip'){skip();return}if(t.id==='global-exit'){globalExit();return}
  if(t.dataset.route){route(t.dataset.route);return}if(t.dataset.locked){log(`${t.dataset.locked} stayed locked. Connect and sync setup to continue.`);return}
  if(t.id==='sync'){if(!state.online){state.error='You are still offline. Restore connection to sync setup.';render();log('Sync stayed blocked while offline.');return}state.pendingEligibility=false;state.screen='question';state.question=0;render();focusHeading();log('Pending eligibility synced. Started question one. No offline action was replayed.');return}
  if(t.id==='sign-out'){state.pendingEligibility=false;state.screen='intro';render();log('Signed out. Cleared pending eligibility for this subject.');return}
  if(t.id==='open-manage'){state.screen='manage';render();return}if(t.id==='home-arya'){route('Ask Arya');return}if(t.id==='home-portfolio'){route('Portfolio');return}if(t.id==='home-goals'){route('Goals');return}if(t.id==='home-tools'){route('Tools');return}
  if(t.id==='dismiss-invite'){state.scenario='complete';state.screen='home';render();log('Legacy invitation dismissed. Access stayed unchanged.');return}
  if(t.id==='voluntary-start'){state.screen='intro';render();log('Opened voluntary setup. Not now remains available before acknowledgement.');return}
  if(t.dataset.edit){state.editing=t.dataset.edit;state.error=null;render();return}if(t.id==='cancel-edit'){state.editing=null;render();log('Edit cancelled. Saved value unchanged.');return}
  if(t.dataset.manageOption){const q=QUESTIONS.find(x=>x.id===t.dataset.question);if(q.multi){toggleExposure(t.dataset.manageOption,true);return}if(state.failNext){state.failNext=false;state.error='We could not save that change just now. Your saved value is unchanged.';render();log('Context change failed. Last authoritative value remained.');return}state.answers[q.id]=t.dataset.manageOption;state.cleared=false;state.editing=null;state.error=null;render();log(`Changed ${q.eyebrow}. Other context stayed unchanged.`);return}
  if(t.id==='save-manage'){state.editing=null;state.cleared=false;state.error=null;render();log('Saved exposure context.');return}if(t.id==='clear'){state.confirmClear=true;render();return}if(t.id==='keep-answers'){state.confirmClear=false;render();log('Clear cancelled. All answers retained.');return}
  if(t.id==='confirm-clear'){if(state.failNext){state.failNext=false;state.error='We could not clear your context just now. Nothing changed.';state.confirmClear=false;render();log('Clear failed. All prior values remained.');return}QUESTIONS.forEach(q=>state.answers[q.id]=q.multi?['undisclosed']:'undisclosed');state.cleared=true;state.confirmClear=false;state.editing=null;state.error=null;render();log('Cleared all personalization context. Progress stayed at one onboarding milestone.');return}
  if(t.id==='back-home'){state.screen='home';render();return}if(t.id==='sign-in'){state.screen='loading';render();log('Entered account recovery. No prior context rendered.');return}
  if(t.id==='relaunch'){const previous=state.screen;state.screen='loading';render();log('Relaunching from authoritative fixture state.');setTimeout(()=>{if(state.handled)state.screen=state.scenario==='manage'?'manage':'home';else if(state.pendingEligibility)state.screen='limited';else if(previous==='intro')state.screen='intro';else state.screen='question';render();focusHeading();log(`Relaunch restored ${state.handled?'handled access':state.pendingEligibility?'limited pending state':`question ${state.question+1}`}.`)},220);return}
  if(t.id==='fail-next'){state.failNext=true;log('Next save or clear will fail once.');return}
  if(t.id==='lose-response'){if(state.screen!=='question'){log('Open a question before simulating a lost response.');return}const q=QUESTIONS[state.question];const value=q.multi?(state.selection.length?[...state.selection]:['saving']):(state.selection[0]||q.options[0][1]);state.answers[q.id]=value;state.lostCommitted={question:q.id,value};state.error='The response was lost after the server saved it. Retry the same choice to reconcile.';render();log('Server committed the choice, but the response was lost. UI did not advance.');return}
  if(t.id==='stale-write'){if(state.screen!=='question'){log('Open a question before simulating a stale write.');return}state.error='Your setup changed elsewhere. Refreshing the current question before you choose again.';render();log('Rejected a different stale write with 409. Authoritative question stayed visible.');return}
  if(t.id==='deny'){state.requestGeneration+=1;state.screen='permission';state.answers=blankAnswers();state.selection=[];state.editing=null;render();log('Permission denied. Cleared all subject context from the view.');return}
  if(t.id==='switch-account'){const from=state.account;const generation=++state.requestGeneration;state.account=from==='Aarav'?'Meera':'Aarav';state.screen='loading';state.answers=blankAnswers();state.selection=[];state.events=[];state.pendingEligibility=false;render();updateLedger();log(`Cleared ${from} before loading ${state.account}.`);setTimeout(()=>{if(generation!==state.requestGeneration)return;state.screen='intro';render();log(`Loaded ${state.account}. Discarded the late ${from} response.`)},260);return}
  if(t.id==='toggle-connection'){state.online=!state.online;t.textContent=state.online?'Go offline':'Restore connection';log(state.online?'Connection restored. Pending setup still requires explicit sync.':'Connection dropped. No request will silently retry.');return}
  if(t.id==='reset'){applyScenario($('scenario').value);return}
});
$('scenario').addEventListener('change',e=>applyScenario(e.target.value));
applyScenario('complete');
